def verify():
    expressions=[]
    for review in REVIEWS:
        baseline=subprocess.check_output(['git','show',BASELINE+':'+review['path']],cwd=ROOT).decode('utf-8-sig').replace('\r\n','\n')
        current=(current_source_path(ROOT, review['path'])).read_text(encoding='utf-8-sig')
        for patch in review['patches']:
            assert baseline.count(patch['before'])==1,'reviewed original Scene layout drift: '+patch['symbol']
            method=ex.declaration(current,patch['signature'].split('(')[0]+'(')
            if patch['after']:
                assert method.count(patch['after'])==1,'actual Scene owner call/argument drift: '+patch['symbol']
            else:
                assert patch['before'] not in method,'duplicate reaction assembly remains: '+patch['symbol']
            if 'BuildSceneSingleSpeakerPrefixSections(' in patch['after']:
                expressions.append(patch['after'])
    assert len(expressions)==5
    return expressions

def callsite_harness():
    expressions=verify()
    cases=[]
    for expression in expressions:
        layout=expression.split('SceneSingleSpeakerLayout.',1)[1].split(',',1)[0]
        cases.append('case MainPromptMessageAssemblyOwner.SceneSingleSpeakerLayout.'+layout+': return '+expression+';')
    return r"""using System;
using System.Text;
using AnimusForge;
internal static class SceneCallSites {
 internal static string[] Read(MainPromptMessageAssemblyOwner.SceneSingleSpeakerLayout layout) {
  string privateRecentWindowSection="private", persistedWithoutRecentWindow="persisted", roleRuntimeContext="runtime",
   currentAfefFactBlock="fact", factText="fact", extraFactUserBlock="fact", trustBlock="trust", miscExtrasSection="misc", scenePatienceInstruction="patience", knowledgeExtrasSection="knowledge", systemRuleBlock="rules";
  var local=new StringBuilder("local"); var sysPrompt=new StringBuilder("local"); var stringBuilder=new StringBuilder("local");
  string sceneDynamicUserBlock="runtime\n\nlocal\n\nfact\n\ntrust\n\nmisc\n\npatience";
  switch(layout) { """+' '.join(cases)+""" default: throw new ArgumentOutOfRangeException(nameof(layout)); }
 }
}
"""
